//! Shadow Balance Management
//!
//! Manages virtual balances for paper trading. Each user has:
//! - Available balance: Funds that can be used for new orders
//! - Reserved balance: Funds locked in open orders
//!
//! # Default Demo Balances
//!
//! New users receive:
//! - 10,000 USDC
//! - 0 BTC (must be earned through trading)
//!
//! # Concurrency (FR-2.3)
//!
//! Uses DashMap for lock-free concurrent access per user.
//! Two different users can modify their balances simultaneously without blocking.

// @anchor exchange:engine:balances
// @tags domain

use dashmap::DashMap;
use rust_decimal::Decimal;
use rust_decimal_macros::dec;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use uuid::Uuid;

use super::ShadowEngineError;

/// A user's balance for a single asset
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ShadowBalance {
    pub asset: String,
    pub available: Decimal,
    pub reserved: Decimal,
}

impl ShadowBalance {
    pub fn new(asset: &str, available: Decimal) -> Self {
        Self {
            asset: asset.to_string(),
            available,
            reserved: dec!(0),
        }
    }

    /// Total balance (available + reserved)
    pub fn total(&self) -> Decimal {
        self.available + self.reserved
    }

    /// Reserve an amount (move from available to reserved)
    pub fn reserve(&mut self, amount: Decimal) -> Result<(), ShadowEngineError> {
        if self.available < amount {
            return Err(ShadowEngineError::BalanceError(format!(
                "Cannot reserve {} {}: only {} available",
                amount, self.asset, self.available
            )));
        }
        self.available -= amount;
        self.reserved += amount;
        // Financial invariant: balances must never go negative
        assert!(self.available >= Decimal::ZERO, "available balance negative after reserve");
        assert!(self.reserved >= Decimal::ZERO, "reserved balance negative after reserve");
        Ok(())
    }

    /// Release reserved amount back to available
    pub fn release(&mut self, amount: Decimal) -> Result<(), ShadowEngineError> {
        if self.reserved < amount {
            return Err(ShadowEngineError::BalanceError(format!(
                "Cannot release {} {}: only {} reserved",
                amount, self.asset, self.reserved
            )));
        }
        self.reserved -= amount;
        self.available += amount;
        assert!(self.available >= Decimal::ZERO, "available balance negative after release");
        assert!(self.reserved >= Decimal::ZERO, "reserved balance negative after release");
        Ok(())
    }

    /// Deduct from reserved (for filled orders)
    pub fn deduct_reserved(&mut self, amount: Decimal) -> Result<(), ShadowEngineError> {
        if self.reserved < amount {
            return Err(ShadowEngineError::BalanceError(format!(
                "Cannot deduct {} {}: only {} reserved",
                amount, self.asset, self.reserved
            )));
        }
        self.reserved -= amount;
        assert!(self.reserved >= Decimal::ZERO, "reserved balance negative after deduct");
        Ok(())
    }

    /// Add to available balance
    pub fn add(&mut self, amount: Decimal) {
        self.available += amount;
        assert!(self.available >= Decimal::ZERO, "available balance negative after add");
    }
}

/// Manages all user balances with lock-free per-user access (FR-2.3)
///
/// Uses DashMap to allow concurrent operations on different users.
/// Two users placing orders simultaneously will not block each other.
pub struct ShadowBalanceManager {
    /// Map of user_id -> asset -> balance
    /// DashMap provides fine-grained locking at the user level
    balances: DashMap<Uuid, HashMap<String, ShadowBalance>>,
}

impl Default for ShadowBalanceManager {
    fn default() -> Self {
        Self::new()
    }
}

impl ShadowBalanceManager {
    pub fn new() -> Self {
        Self {
            balances: DashMap::new(),
        }
    }

    /// Initialize a user with default demo balances
    /// Default: 10,000 USDT for perpetual futures trading
    pub fn init_user_with_defaults(&self, user_id: Uuid) {
        let mut user_balances = HashMap::new();

        // Default demo balance: 10,000 USDT (margin for perpetual futures)
        user_balances.insert("USDT".to_string(), ShadowBalance::new("USDT", dec!(10000)));

        self.balances.insert(user_id, user_balances);
    }

    /// Reset a user's balances to default demo amounts
    /// Clears any existing balances and positions, giving a fresh start
    pub fn reset_user_to_defaults(&self, user_id: Uuid) {
        // Remove existing balances
        self.balances.remove(&user_id);
        // Re-initialize with defaults
        self.init_user_with_defaults(user_id);
    }

    /// Check if a user has been initialized
    pub fn user_exists(&self, user_id: Uuid) -> bool {
        self.balances.contains_key(&user_id)
    }

    /// Set a specific balance for a user
    pub fn set_balance(&self, user_id: Uuid, asset: &str, amount: Decimal) {
        self.balances
            .entry(user_id)
            .or_insert_with(HashMap::new)
            .insert(asset.to_string(), ShadowBalance::new(asset, amount));
    }

    /// Get all balances for a user
    pub fn get_user_balances(&self, user_id: Uuid) -> Vec<ShadowBalance> {
        self.balances
            .get(&user_id)
            .map(|balances| balances.values().cloned().collect())
            .unwrap_or_default()
    }

    /// Get available balance for a specific asset
    pub fn get_available(&self, user_id: Uuid, asset: &str) -> Decimal {
        self.balances
            .get(&user_id)
            .and_then(|balances| balances.get(asset).map(|b| b.available))
            .unwrap_or(dec!(0))
    }

    /// Get total balance for a specific asset
    pub fn get_total(&self, user_id: Uuid, asset: &str) -> Decimal {
        self.balances
            .get(&user_id)
            .and_then(|balances| balances.get(asset).map(|b| b.total()))
            .unwrap_or(dec!(0))
    }

    /// Reserve funds for an order
    pub fn reserve(
        &self,
        user_id: Uuid,
        asset: &str,
        amount: Decimal,
    ) -> Result<(), ShadowEngineError> {
        let mut user_balances = self.balances.entry(user_id).or_insert_with(HashMap::new);
        let balance = user_balances
            .entry(asset.to_string())
            .or_insert_with(|| ShadowBalance::new(asset, dec!(0)));
        balance.reserve(amount)
    }

    /// Release reserved funds (order cancelled)
    pub fn release(
        &self,
        user_id: Uuid,
        asset: &str,
        amount: Decimal,
    ) -> Result<(), ShadowEngineError> {
        let mut user_balances = self
            .balances
            .get_mut(&user_id)
            .ok_or_else(|| ShadowEngineError::BalanceError("User not found".to_string()))?;

        let balance = user_balances
            .get_mut(asset)
            .ok_or_else(|| ShadowEngineError::BalanceError("Asset not found".to_string()))?;

        balance.release(amount)
    }

    /// Add to available balance
    pub fn add(&self, user_id: Uuid, asset: &str, amount: Decimal) {
        let mut user_balances = self.balances.entry(user_id).or_insert_with(HashMap::new);
        let balance = user_balances
            .entry(asset.to_string())
            .or_insert_with(|| ShadowBalance::new(asset, dec!(0)));
        balance.add(amount);
    }

    /// Deduct from reserved (for fills)
    pub fn deduct_reserved(
        &self,
        user_id: Uuid,
        asset: &str,
        amount: Decimal,
    ) -> Result<(), ShadowEngineError> {
        let mut user_balances = self
            .balances
            .get_mut(&user_id)
            .ok_or_else(|| ShadowEngineError::BalanceError("User not found".to_string()))?;

        let balance = user_balances
            .get_mut(asset)
            .ok_or_else(|| ShadowEngineError::BalanceError("Asset not found".to_string()))?;

        balance.deduct_reserved(amount)
    }

    /// Get user's equity in a specific quote currency (e.g., USDC)
    ///
    /// This is the total value of all holdings converted to the quote currency.
    /// Requires current prices for conversion.
    pub fn calculate_equity(
        &self,
        user_id: Uuid,
        quote_currency: &str,
        prices: &HashMap<String, Decimal>,
    ) -> Decimal {
        let user_balances = match self.balances.get(&user_id) {
            Some(b) => b,
            None => return dec!(0),
        };

        let mut total = dec!(0);

        for (asset, balance) in user_balances.iter() {
            if asset == quote_currency {
                total += balance.total();
            } else {
                // Look up price for this asset in quote currency
                let price_key = format!("{}_{}", asset, quote_currency);
                if let Some(price) = prices.get(&price_key) {
                    total += balance.total() * price;
                }
            }
        }

        total
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_shadow_balance_creation() {
        let balance = ShadowBalance::new("USDC", dec!(1000));
        assert_eq!(balance.asset, "USDC");
        assert_eq!(balance.available, dec!(1000));
        assert_eq!(balance.reserved, dec!(0));
        assert_eq!(balance.total(), dec!(1000));
    }

    #[test]
    fn test_balance_reserve_and_release() {
        let mut balance = ShadowBalance::new("USDC", dec!(1000));

        // Reserve some
        balance.reserve(dec!(400)).unwrap();
        assert_eq!(balance.available, dec!(600));
        assert_eq!(balance.reserved, dec!(400));
        assert_eq!(balance.total(), dec!(1000));

        // Release some
        balance.release(dec!(100)).unwrap();
        assert_eq!(balance.available, dec!(700));
        assert_eq!(balance.reserved, dec!(300));

        // Try to reserve too much
        let result = balance.reserve(dec!(800));
        assert!(result.is_err());
    }

    #[test]
    fn test_balance_manager_init_user() {
        let manager = ShadowBalanceManager::new();
        let user_id = Uuid::new_v4();

        manager.init_user_with_defaults(user_id);

        // Default is 10,000 USDT for perpetual futures margin
        let usdt = manager.get_available(user_id, "USDT");
        assert_eq!(usdt, dec!(10000));

        // Non-existent assets return 0
        let btc = manager.get_available(user_id, "BTC");
        assert_eq!(btc, dec!(0));
    }

    #[test]
    fn test_balance_manager_reset_user() {
        let manager = ShadowBalanceManager::new();
        let user_id = Uuid::new_v4();

        manager.init_user_with_defaults(user_id);

        // Modify the balance
        manager.add(user_id, "USDT", dec!(5000));
        assert_eq!(manager.get_available(user_id, "USDT"), dec!(15000));

        // Reset should restore to default
        manager.reset_user_to_defaults(user_id);
        assert_eq!(manager.get_available(user_id, "USDT"), dec!(10000));
    }

    #[test]
    fn test_balance_manager_user_exists() {
        let manager = ShadowBalanceManager::new();
        let user_id = Uuid::new_v4();

        assert!(!manager.user_exists(user_id));
        manager.init_user_with_defaults(user_id);
        assert!(manager.user_exists(user_id));
    }

    #[test]
    fn test_balance_manager_reserve_release() {
        let manager = ShadowBalanceManager::new();
        let user_id = Uuid::new_v4();

        manager.init_user_with_defaults(user_id);

        // Reserve some USDT
        manager.reserve(user_id, "USDT", dec!(500)).unwrap();
        assert_eq!(manager.get_available(user_id, "USDT"), dec!(9500));
        assert_eq!(manager.get_total(user_id, "USDT"), dec!(10000));

        // Release it back
        manager.release(user_id, "USDT", dec!(500)).unwrap();
        assert_eq!(manager.get_available(user_id, "USDT"), dec!(10000));
    }

    #[test]
    fn test_balance_manager_add() {
        let manager = ShadowBalanceManager::new();
        let user_id = Uuid::new_v4();

        manager.init_user_with_defaults(user_id);

        // Add some BTC (simulating a fill)
        manager.add(user_id, "BTC", dec!(0.5));
        assert_eq!(manager.get_available(user_id, "BTC"), dec!(0.5));
    }

    #[test]
    fn test_calculate_equity() {
        let manager = ShadowBalanceManager::new();
        let user_id = Uuid::new_v4();

        manager.set_balance(user_id, "USDC", dec!(5000));
        manager.set_balance(user_id, "BTC", dec!(0.1));

        let mut prices = HashMap::new();
        prices.insert("BTC_USDC".to_string(), dec!(50000));

        let equity = manager.calculate_equity(user_id, "USDC", &prices);
        // 5000 USDC + 0.1 BTC * 50000 = 5000 + 5000 = 10000
        assert_eq!(equity, dec!(10000));
    }
}

//! Shadow Order Management
//!
//! Manages virtual orders for paper trading. Orders are checked against
//! live market data and filled when conditions are met.
//!
//! # Fill Logic (from PRD)
//!
//! - **Buy Limit**: Fills if `Low Price <= Limit Price`
//! - **Sell Limit**: Fills if `High Price >= Limit Price`
//! - **Buy Market**: Fills immediately at `Best Ask`
//! - **Sell Market**: Fills immediately at `Best Bid`
//! - **Stop Loss Buy**: Triggers when `High Price >= Stop Price`
//! - **Stop Loss Sell**: Triggers when `Low Price <= Stop Price`

// @anchor exchange:engine:orders
// @tags domain

use chrono::{DateTime, Utc};
use rust_decimal::Decimal;
use rust_decimal_macros::dec;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::time::Instant;
use uuid::Uuid;

use super::ShadowEngineError;

/// Order side - buy or sell
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ShadowOrderSide {
    Buy,
    Sell,
}

/// Order type
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ShadowOrderType {
    Market,
    Limit,
    StopLoss,
    TakeProfit,
}

/// Order status
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ShadowOrderStatus {
    Open,
    Filled,
    PartiallyFilled,
    Cancelled,
    Rejected,
}

/// A shadow (paper trading) order
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ShadowOrder {
    pub id: Uuid,
    pub user_id: Uuid,
    pub symbol: String,
    pub side: ShadowOrderSide,
    pub order_type: ShadowOrderType,
    pub quantity: Decimal,
    pub filled_quantity: Decimal,
    pub price: Option<Decimal>,      // For limit orders
    pub stop_price: Option<Decimal>, // For stop/take-profit orders
    pub average_fill_price: Option<Decimal>,
    pub status: ShadowOrderStatus,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
    pub filled_at: Option<DateTime<Utc>>,

    // Optional linked orders for trade management
    pub stop_loss_price: Option<Decimal>,
    pub take_profit_price: Option<Decimal>,
    pub parent_order_id: Option<Uuid>,

    /// Risk validation flag - must be true for order to be accepted by Shadow Engine.
    /// Set to true by the Decision Loop after risk validation passes.
    /// Orders with risk_validated = false will be rejected by ShadowEngine::place_order().
    #[serde(default)]
    pub risk_validated: bool,

    /// Leverage multiplier for margin calculation (1 = no leverage).
    /// Margin required = notional / leverage. Per-pair limits enforced at exchange.
    #[serde(default = "default_leverage")]
    pub leverage: u8,

    /// AUD-02: Timestamp when order reached terminal state (for GC).
    #[serde(skip)]
    pub completed_at: Option<Instant>,
}

fn default_leverage() -> u8 {
    1
}

impl ShadowOrder {
    /// Create a new shadow order
    ///
    /// Note: Orders are created with `risk_validated = false` by default.
    /// Use `mark_risk_validated()` after passing Decision Loop validation.
    pub fn new(
        user_id: Uuid,
        symbol: String,
        side: ShadowOrderSide,
        order_type: ShadowOrderType,
        quantity: Decimal,
        price: Option<Decimal>,
        stop_price: Option<Decimal>,
        parent_order_id: Option<Uuid>,
    ) -> Self {
        let now = Utc::now();
        Self {
            id: Uuid::new_v4(),
            user_id,
            symbol,
            side,
            order_type,
            quantity,
            filled_quantity: dec!(0),
            price,
            stop_price,
            average_fill_price: None,
            status: ShadowOrderStatus::Open,
            created_at: now,
            updated_at: now,
            filled_at: None,
            stop_loss_price: None,
            take_profit_price: None,
            parent_order_id,
            risk_validated: false,
            leverage: 1,
            completed_at: None,
        }
    }

    /// Mark this order as risk-validated.
    ///
    /// Called by the Decision Loop after the order passes risk checks.
    /// Orders must have `risk_validated = true` to be accepted by Shadow Engine.
    pub fn mark_risk_validated(&mut self) {
        self.risk_validated = true;
        log::info!(
            "Order {} marked as risk validated (symbol={}, side={:?}, qty={})",
            self.id,
            self.symbol,
            self.side,
            self.quantity
        );
    }

    /// Check if this order has been risk-validated
    pub fn is_risk_validated(&self) -> bool {
        self.risk_validated
    }

    /// Create a market buy order
    pub fn market_buy(user_id: Uuid, symbol: &str, quantity: Decimal) -> Self {
        Self::new(
            user_id,
            symbol.to_string(),
            ShadowOrderSide::Buy,
            ShadowOrderType::Market,
            quantity,
            None,
            None,
            None,
        )
    }

    /// Create a market sell order
    pub fn market_sell(user_id: Uuid, symbol: &str, quantity: Decimal) -> Self {
        Self::new(
            user_id,
            symbol.to_string(),
            ShadowOrderSide::Sell,
            ShadowOrderType::Market,
            quantity,
            None,
            None,
            None,
        )
    }

    /// Create a limit buy order
    pub fn limit_buy(user_id: Uuid, symbol: &str, quantity: Decimal, price: Decimal) -> Self {
        Self::new(
            user_id,
            symbol.to_string(),
            ShadowOrderSide::Buy,
            ShadowOrderType::Limit,
            quantity,
            Some(price),
            None,
            None,
        )
    }

    /// Create a limit sell order
    pub fn limit_sell(user_id: Uuid, symbol: &str, quantity: Decimal, price: Decimal) -> Self {
        Self::new(
            user_id,
            symbol.to_string(),
            ShadowOrderSide::Sell,
            ShadowOrderType::Limit,
            quantity,
            Some(price),
            None,
            None,
        )
    }

    /// Get the asset required for this order (futures: always quote currency margin).
    /// Normalizes "USD" → "USDT" since perpetual futures margin is always USDT.
    pub fn required_asset(&self) -> String {
        let (_base, quote) = self.symbol_parts();
        // Perpetual futures: "USD" pairs settle in USDT
        if quote == "USD" {
            "USDT".to_string()
        } else {
            quote
        }
    }

    /// Get the margin required for this order (futures: notional / leverage)
    pub fn required_amount(&self) -> Decimal {
        let price = self.price.unwrap_or(dec!(0));
        let notional = self.quantity * price;
        notional / Decimal::from(self.leverage.max(1))
    }

    /// Parse symbol into base and quote assets
    pub fn symbol_parts(&self) -> (String, String) {
        let parts: Vec<&str> = self.symbol.split('_').collect();
        if parts.len() == 2 {
            (parts[0].to_string(), parts[1].to_string())
        } else {
            // Fallback for symbols like "BTCUSDC"
            // Assume last 4 chars are quote for USDC/USDT
            if self.symbol.ends_with("USDC") {
                let base = &self.symbol[..self.symbol.len() - 4];
                (base.to_string(), "USDC".to_string())
            } else if self.symbol.ends_with("USDT") {
                let base = &self.symbol[..self.symbol.len() - 4];
                (base.to_string(), "USDT".to_string())
            } else {
                (self.symbol.clone(), "USDC".to_string())
            }
        }
    }

    /// Check if this order should fill at the given market prices.
    ///
    /// Uses current bid/ask for real-time fill checking (live price feed).
    /// - bid = best price someone will buy at (what you get when selling)
    /// - ask = best price someone will sell at (what you pay when buying)
    pub fn should_fill(&self, bid: Decimal, ask: Decimal, _high: Decimal, _low: Decimal) -> bool {
        match (&self.order_type, &self.side) {
            // Market orders fill immediately
            (ShadowOrderType::Market, _) => true,

            // Limit buy fills when ask drops to or below limit price
            (ShadowOrderType::Limit, ShadowOrderSide::Buy) => {
                self.price.map(|p| ask <= p).unwrap_or(false)
            }

            // Limit sell fills when bid rises to or above limit price
            (ShadowOrderType::Limit, ShadowOrderSide::Sell) => {
                self.price.map(|p| bid >= p).unwrap_or(false)
            }

            // Stop loss buy (short SL) triggers when ask rises to stop price
            (ShadowOrderType::StopLoss, ShadowOrderSide::Buy) => {
                self.stop_price.map(|p| ask >= p).unwrap_or(false)
            }

            // Stop loss sell (long SL) triggers when bid drops to stop price
            (ShadowOrderType::StopLoss, ShadowOrderSide::Sell) => {
                self.stop_price.map(|p| bid <= p).unwrap_or(false)
            }

            // Take profit buy (short TP) triggers when ask drops to target
            (ShadowOrderType::TakeProfit, ShadowOrderSide::Buy) => {
                self.stop_price.map(|p| ask <= p).unwrap_or(false)
            }

            // Take profit sell (long TP) triggers when bid rises to target
            (ShadowOrderType::TakeProfit, ShadowOrderSide::Sell) => {
                self.stop_price.map(|p| bid >= p).unwrap_or(false)
            }
        }
    }

    /// Fill this order at the given price
    pub fn fill(&mut self, fill_price: Decimal) {
        assert!(
            self.is_open(),
            "Cannot fill order {} — status is {:?}",
            self.id,
            self.status
        );
        self.filled_quantity = self.quantity;
        self.average_fill_price = Some(fill_price);
        self.status = ShadowOrderStatus::Filled;
        self.filled_at = Some(Utc::now());
        self.updated_at = Utc::now();
        self.completed_at = Some(Instant::now());
    }

    /// Cancel this order
    pub fn cancel(&mut self) {
        assert!(
            self.is_open(),
            "Cannot cancel order {} — status is {:?}",
            self.id,
            self.status
        );
        self.status = ShadowOrderStatus::Cancelled;
        self.updated_at = Utc::now();
        self.completed_at = Some(Instant::now());
    }

    /// Check if order is still open
    pub fn is_open(&self) -> bool {
        matches!(
            self.status,
            ShadowOrderStatus::Open | ShadowOrderStatus::PartiallyFilled
        )
    }

    /// Set leverage for this order (affects margin calculation)
    pub fn with_leverage(mut self, leverage: u8) -> Self {
        self.leverage = leverage.max(1);
        self
    }

    /// Set stop loss price for this order
    pub fn with_stop_loss(mut self, price: Decimal) -> Self {
        self.stop_loss_price = Some(price);
        self
    }

    /// Set take profit price for this order
    pub fn with_take_profit(mut self, price: Decimal) -> Self {
        self.take_profit_price = Some(price);
        self
    }
}

/// Manages all shadow orders
pub struct ShadowOrderManager {
    /// All orders by ID
    orders: HashMap<Uuid, ShadowOrder>,
    /// Index of orders by user
    orders_by_user: HashMap<Uuid, Vec<Uuid>>,
    /// Index of open orders by symbol
    open_orders_by_symbol: HashMap<String, Vec<Uuid>>,
}

impl Default for ShadowOrderManager {
    fn default() -> Self {
        Self::new()
    }
}

impl ShadowOrderManager {
    pub fn new() -> Self {
        Self {
            orders: HashMap::new(),
            orders_by_user: HashMap::new(),
            open_orders_by_symbol: HashMap::new(),
        }
    }

    /// Add a new order
    pub fn add_order(&mut self, user_id: Uuid, mut order: ShadowOrder) -> ShadowOrder {
        order.user_id = user_id;
        let order_id = order.id;
        let symbol = order.symbol.clone();

        // Store the order
        self.orders.insert(order_id, order.clone());

        // Index by user
        self.orders_by_user
            .entry(user_id)
            .or_default()
            .push(order_id);

        // Index open orders by symbol
        if order.is_open() {
            self.open_orders_by_symbol
                .entry(symbol)
                .or_default()
                .push(order_id);
        }

        order
    }

    /// Get all open orders for a user
    pub fn get_open_orders(&self, user_id: Uuid) -> Vec<ShadowOrder> {
        self.orders_by_user
            .get(&user_id)
            .map(|order_ids| {
                order_ids
                    .iter()
                    .filter_map(|id| self.orders.get(id))
                    .filter(|o| o.is_open())
                    .cloned()
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Get all orders for a user (including filled/cancelled)
    pub fn get_all_orders(&self, user_id: Uuid) -> Vec<ShadowOrder> {
        self.orders_by_user
            .get(&user_id)
            .map(|order_ids| {
                order_ids
                    .iter()
                    .filter_map(|id| self.orders.get(id))
                    .cloned()
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Get a specific order
    pub fn get_order(&self, order_id: Uuid) -> Option<&ShadowOrder> {
        self.orders.get(&order_id)
    }

    /// Cancel an order
    pub fn cancel_order(
        &mut self,
        user_id: Uuid,
        order_id: Uuid,
    ) -> Result<ShadowOrder, ShadowEngineError> {
        let order = self
            .orders
            .get_mut(&order_id)
            .ok_or(ShadowEngineError::OrderNotFound(order_id))?;

        if order.user_id != user_id {
            return Err(ShadowEngineError::OrderNotFound(order_id));
        }

        if !order.is_open() {
            return Err(ShadowEngineError::InvalidOrder(
                "Order is not open".to_string(),
            ));
        }

        order.cancel();

        // Remove from open orders index
        if let Some(ids) = self.open_orders_by_symbol.get_mut(&order.symbol) {
            ids.retain(|id| *id != order_id);
        }

        Ok(order.clone())
    }

    /// Check for orders that should fill at current prices (READ-ONLY)
    ///
    /// Returns copies of orders that would trigger at the given prices.
    /// Does NOT modify any state - use `apply_fills` to actually fill orders.
    ///
    /// Part of the Read-Compute-Write pattern (004-read-compute-write):
    /// - READ: This method - identify triggerable orders without locking
    /// - COMPUTE: Calculate fills in memory
    /// - WRITE: `apply_fills` - update state atomically
    pub fn get_triggerable_orders(
        &self,
        symbol: &str,
        bid: Decimal,
        ask: Decimal,
        high: Decimal,
        low: Decimal,
    ) -> Vec<ShadowOrder> {
        let order_ids: Vec<Uuid> = self
            .open_orders_by_symbol
            .get(symbol)
            .cloned()
            .unwrap_or_default();

        order_ids
            .iter()
            .filter_map(|order_id| self.orders.get(order_id))
            .filter(|order| order.should_fill(bid, ask, high, low))
            .cloned()
            .collect()
    }

    /// Apply fills to orders (WRITE operation)
    ///
    /// Marks orders as filled and removes them from the open orders index.
    /// Part of the Read-Compute-Write pattern - call after computing fills.
    pub fn apply_fills(&mut self, order_ids: &[Uuid]) {
        for order_id in order_ids {
            if let Some(order) = self.orders.get(order_id) {
                let symbol = order.symbol.clone();

                // Remove from open orders index
                if let Some(ids) = self.open_orders_by_symbol.get_mut(&symbol) {
                    ids.retain(|id| id != order_id);
                }
            }

            // Update the order status
            if let Some(stored_order) = self.orders.get_mut(order_id) {
                stored_order.status = ShadowOrderStatus::Filled;
                stored_order.completed_at = Some(Instant::now());
            }
        }
    }

    /// Check for orders that should fill at current prices
    ///
    /// Returns orders that have been filled (removed from open orders)
    ///
    /// DEPRECATED: Use `get_triggerable_orders` + `apply_fills` for the
    /// Read-Compute-Write pattern which minimizes lock contention.
    pub fn check_fills(
        &mut self,
        symbol: &str,
        bid: Decimal,
        ask: Decimal,
        high: Decimal,
        low: Decimal,
    ) -> Vec<ShadowOrder> {
        let mut filled = Vec::new();

        let order_ids: Vec<Uuid> = self
            .open_orders_by_symbol
            .get(symbol)
            .cloned()
            .unwrap_or_default();

        for order_id in order_ids {
            if let Some(order) = self.orders.get(&order_id) {
                if order.should_fill(bid, ask, high, low) {
                    filled.push(order.clone());
                }
            }
        }

        // Remove filled orders from the open index
        for order in &filled {
            if let Some(ids) = self.open_orders_by_symbol.get_mut(&order.symbol) {
                ids.retain(|id| *id != order.id);
            }
            // Update the order status in our storage
            if let Some(stored_order) = self.orders.get_mut(&order.id) {
                stored_order.status = ShadowOrderStatus::Filled;
                stored_order.completed_at = Some(Instant::now());
            }
        }

        filled
    }

    /// Get all symbols that currently have open orders
    ///
    /// Used by PriceFeedService to know which symbols need price polling.
    /// Returns a deduplicated list of symbols with at least one open order.
    pub fn get_active_symbols(&self) -> Vec<String> {
        self.open_orders_by_symbol
            .iter()
            .filter(|(_, ids)| !ids.is_empty())
            .map(|(symbol, _)| symbol.clone())
            .collect()
    }

    /// Get count of open orders
    pub fn open_order_count(&self) -> usize {
        self.orders.values().filter(|o| o.is_open()).count()
    }

    /// AUD-02 FR-1: Remove terminal orders older than cutoff.
    pub fn prune_terminal(&mut self, cutoff: Instant) -> usize {
        let to_remove: Vec<Uuid> = self
            .orders
            .iter()
            .filter(|(_, o)| {
                !o.is_open() && o.completed_at.is_some_and(|t| t < cutoff)
            })
            .map(|(id, _)| *id)
            .collect();

        for id in &to_remove {
            self.orders.remove(id);
        }

        // Clean orders_by_user
        for ids in self.orders_by_user.values_mut() {
            ids.retain(|id| !to_remove.contains(id));
        }

        to_remove.len()
    }

    /// Update the stop price of an existing order (for break-even)
    pub fn update_stop_price(&mut self, order_id: Uuid, new_stop_price: Decimal) -> bool {
        if let Some(order) = self.orders.get_mut(&order_id) {
            order.stop_price = Some(new_stop_price);
            order.updated_at = chrono::Utc::now();
            true
        } else {
            false
        }
    }
}

