// ── Unit tests ────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_summary_format_default_is_json() {
        assert_eq!(SummaryFormat::default(), SummaryFormat::Json);
    }

    #[test]
    fn test_summary_format_deser_lowercase() {
        let json: SummaryFormat = serde_json::from_str("\"json\"").unwrap();
        assert_eq!(json, SummaryFormat::Json);

        let llm: SummaryFormat = serde_json::from_str("\"llm\"").unwrap();
        assert_eq!(llm, SummaryFormat::Llm);
    }

    #[test]
    fn test_pattern_kind_serde_roundtrip() {
        let variants = [
            PatternKind::SizingDrift,
            PatternKind::FrequencySpike,
            PatternKind::SessionAnomaly,
            PatternKind::SetupFatigue,
            PatternKind::CorrelationStack,
            PatternKind::StreakRisk,
        ];
        for v in &variants {
            let json = serde_json::to_string(v).unwrap();
            let back: PatternKind = serde_json::from_str(&json).unwrap();
            assert_eq!(*v, back);
        }
    }

    #[test]
    fn test_severity_serde_roundtrip() {
        let variants = [Severity::Info, Severity::Notable, Severity::Concerning];
        for v in &variants {
            let json = serde_json::to_string(v).unwrap();
            let back: Severity = serde_json::from_str(&json).unwrap();
            assert_eq!(*v, back);
        }
    }

    #[test]
    fn test_delta_direction_serde() {
        assert_eq!(
            serde_json::to_string(&DeltaDirection::Improved).unwrap(),
            "\"improved\""
        );
        assert_eq!(
            serde_json::to_string(&DeltaDirection::Declined).unwrap(),
            "\"declined\""
        );
        assert_eq!(
            serde_json::to_string(&DeltaDirection::Neutral).unwrap(),
            "\"neutral\""
        );
    }

    #[test]
    fn test_compare_request_deser() {
        let json = r#"{
            "period_a": {"from": "2026-01-01", "to": "2026-03-31"},
            "period_b": {"from": "2026-04-01", "to": "2026-06-30"},
            "filters": {"symbol": "ETH_USDT", "source": "agent:hermes_v1.2"}
        }"#;
        let req: CompareRequest = serde_json::from_str(json).unwrap();
        assert_eq!(req.period_a.from.to_string(), "2026-01-01");
        assert_eq!(req.period_b.to.to_string(), "2026-06-30");
        let f = req.filters.unwrap();
        assert_eq!(f.symbol.unwrap(), "ETH_USDT");
        assert_eq!(f.source.unwrap(), "agent:hermes_v1.2");
    }

    #[test]
    fn test_agent_summary_query_deser_defaults() {
        // JSON with empty/missing fields should produce defaults
        let q: AgentSummaryQuery = serde_json::from_str("{}").unwrap();
        assert!(q.timeframe.is_none());
        assert_eq!(q.format, SummaryFormat::Json);
    }

    #[test]
    fn test_agent_summary_query_deser_full() {
        let json = r#"{
            "timeframe": "30d",
            "symbol": "ETH_USDT",
            "side": "LONG",
            "setup_tag": "breakout",
            "exchange": "hyperliquid",
            "source": "agent:hermes_v1.2",
            "format": "llm"
        }"#;
        let q: AgentSummaryQuery = serde_json::from_str(json).unwrap();
        assert_eq!(q.timeframe.unwrap(), "30d");
        assert_eq!(q.symbol.unwrap(), "ETH_USDT");
        assert_eq!(q.side.unwrap(), "LONG");
        assert_eq!(q.setup_tag.unwrap(), "breakout");
        assert_eq!(q.exchange.unwrap(), "hyperliquid");
        assert_eq!(q.source.unwrap(), "agent:hermes_v1.2");
        assert_eq!(q.format, SummaryFormat::Llm);
    }
}

//! Agent API key types — scoped credentials for autonomous trading agents.
//!
//! Keys are SHA-256 hashed at rest, irrecoverable after creation, independently
//! revocable. Each key carries a permission set that limits what the agent can do.

// @anchor exchange:router:agent-key-types
// @tags api

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;
use validator::Validate;

// AUTH-03: Permission, AuthMethod, and AgentKeyClaims now live in the policy module.
pub use crate::policy::{AgentKeyClaims, AuthMethod, Permission};

/// Default permission set for trading agents.
/// Sufficient for the autonomous trading loop: signal + journal read/write.
pub fn default_agent_permissions() -> Vec<Permission> {
    crate::policy::default_permissions()
}

// ── Request types ─────────────────────────────────────────────────────

/// Request to create a new agent API key.
#[derive(Debug, Deserialize, Validate)]
pub struct CreateAgentKeyRequest {
    #[validate(length(min = 1, max = 128))]
    pub name: String,

    #[serde(default = "default_agent_permissions")]
    pub permissions: Vec<Permission>,

    /// Days until expiry. None = never expires (until revoked). Max 365.
    #[validate(range(min = 1, max = 365))]
    pub expires_in_days: Option<i32>,
}

/// Request to update an agent key (partial update).
#[derive(Debug, Deserialize, Validate)]
pub struct UpdateAgentKeyRequest {
    #[validate(length(min = 1, max = 128))]
    pub name: Option<String>,
    pub permissions: Option<Vec<Permission>>,
}

// ── Response types ─────────────────────────────────────────────────────

/// Returned at creation time — includes the raw key. Only shown once.
#[derive(Debug, Serialize)]
pub struct CreateAgentKeyResponse {
    pub id: Uuid,
    pub name: String,
    pub key: String,
    pub permissions: Vec<Permission>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub expires_at: Option<DateTime<Utc>>,
    pub created_at: DateTime<Utc>,
}

/// Returned when listing keys — NO raw key value.
#[derive(Debug, Serialize)]
pub struct AgentKeySummary {
    pub id: Uuid,
    pub name: String,
    pub key_prefix: String,
    pub permissions: Vec<Permission>,
    pub created_at: DateTime<Utc>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub expires_at: Option<DateTime<Utc>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub last_used_at: Option<DateTime<Utc>>,
    pub is_revoked: bool,
}

// ── DB row type ────────────────────────────────────────────────────────

/// Row from the `agent_keys` table.
#[derive(Debug, sqlx::FromRow)]
pub struct AgentKeyRow {
    pub id: Uuid,
    pub user_id: Uuid,
    pub name: String,
    pub key_hash: String,
    pub key_prefix: String,
    pub permissions: serde_json::Value,
    pub created_at: DateTime<Utc>,
    pub expires_at: Option<DateTime<Utc>>,
    pub last_used_at: Option<DateTime<Utc>>,
    pub is_revoked: bool,
    pub revoked_at: Option<DateTime<Utc>>,
}

//! Agent Signal Types
//!
//! Wire-level types for the POST /api/v1/signals endpoint.
//! SignalInput is deserialized from the agent's JSON payload;
//! SignalResult is the structured response returned after
//! the risk engine processes the signal.

// @anchor exchange:router:agent_signal
// @tags api

use rust_decimal::Decimal;
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use common_utils::risk::SizingMethod;

/// Signal submitted by an external agent.
#[derive(Debug, Deserialize)]
pub struct SignalInput {
    pub symbol: String,
    pub side: SignalSide,
    pub entry_price: Decimal,
    pub stop_loss: Option<Decimal>,
    pub take_profit: Vec<TakeProfitTarget>,
    pub exchange_account_id: Option<Uuid>,
    pub execution_mode: ExecutionMode,
    pub reasoning: Option<String>,
    /// Agent identifier, e.g. "agent:hermes_v1.2"
    pub source: Option<String>,
    /// 0.0–1.0, stored for Kelly calibration
    pub confidence: Option<Decimal>,
    pub idempotency_key: Option<Uuid>,
    pub leverage: Option<u8>,
    pub management: Option<SignalManagement>,
}

#[derive(Debug, Deserialize)]
pub struct TakeProfitTarget {
    pub price: Decimal,
    pub quantity: Decimal,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "UPPERCASE")]
pub enum SignalSide {
    Long,
    Short,
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(rename_all = "UPPERCASE")]
pub enum ExecutionMode {
    Shadow,
    Live,
}

#[derive(Debug, Deserialize)]
pub struct SignalManagement {
    pub break_even_enabled: Option<bool>,
    pub break_even_at: Option<Decimal>,
    pub trailing_stop: Option<TrailingStopConfig>,
    pub partial_tp: Option<PartialTpConfig>,
}

#[derive(Debug, Deserialize)]
pub struct TrailingStopConfig {
    pub enabled: bool,
    pub distance_percent: u32,
}

#[derive(Debug, Deserialize)]
pub struct PartialTpConfig {
    pub enabled: bool,
    pub close_percent: u32,
}

/// Structured result returned to the agent after signal processing.
#[derive(Debug, Serialize)]
pub struct SignalResult {
    pub success: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub trade_group_id: Option<Uuid>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub entry_order_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub position_size: Option<Decimal>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub sizing_method: Option<SizingMethod>,
    pub execution_mode: ExecutionMode,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub warnings: Vec<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub agent_key_id: Option<Uuid>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub rejection: Option<SignalRejection>,
}

#[derive(Debug, Serialize)]
pub struct SignalRejection {
    pub reason: String,
    pub code: String,
}

impl SignalResult {
    pub fn success(
        trade_group_id: Uuid,
        entry_order_id: String,
        position_size: Decimal,
        sizing_method: SizingMethod,
        execution_mode: ExecutionMode,
        warnings: Vec<String>,
        agent_key_id: Option<Uuid>,
    ) -> Self {
        Self {
            success: true,
            trade_group_id: Some(trade_group_id),
            entry_order_id: Some(entry_order_id),
            position_size: Some(position_size),
            sizing_method: Some(sizing_method),
            execution_mode,
            warnings,
            agent_key_id,
            rejection: None,
        }
    }

    pub fn rejected(reason: String, code: String, execution_mode: ExecutionMode) -> Self {
        Self {
            success: false,
            trade_group_id: None,
            entry_order_id: None,
            position_size: None,
            sizing_method: None,
            execution_mode,
            warnings: Vec::new(),
            agent_key_id: None,
            rejection: Some(SignalRejection { reason, code }),
        }
    }
}

//! CCXT-Compatible Types
//!
//! This module defines types that align with the official CCXT library patterns,
//! providing a standardized interface for cryptocurrency exchange integration.
//!
//! # CCXT Patterns
//!
//! The types follow the official CCXT JavaScript/TypeScript library conventions:
//! - Unified method signatures across all exchanges
//! - Standardized error codes and messages
//! - Consistent parameter and response formats
//! - Symbol normalization across exchange-specific formats

