    /// Fetch order status from the exchange
    ///
    /// # Arguments
    ///
    /// * `order_id` - The order ID to fetch
    /// * `symbol` - Trading pair symbol
    ///
    /// # Returns
    ///
    /// CCXTOrderResponse with current order state
    pub async fn fetch_order(
        &self,
