fn extract_node_health(
    graph: &SheafGraph,
    now: i64,
    signals: &mut Vec<proto::TopologySignal>,
) {
    debug_assert!(now > 0, "timestamp must be positive");

    for (id, node) in &graph.nodes {
        match node.status {
            crate::graph::NodeStatus::Stale { since }
                if now - since < 200_000_000 =>
            {
                signals.push(proto::TopologySignal {
                        r#type: proto::SignalType::NodeStale as i32,
                        severity: proto::Severity::Notable as i32,
                        context: format!(
                            "{}:{} no tick data for {}s. Venue may be throttling.",
                            id.venue, id.symbol, (now - since) / 1_000_000_000
                        ),
                        first_seen_ns: since,
                        duration_windows: 1,
                        signal_data: Some(
                            proto::topology_signal::SignalData::NodeHealth(
                                proto::NodeHealthSignal {
                                    venue: id.venue.clone(),
                                    symbol: id.symbol.clone(),
                                    event: "stale".into(),
                                    since_ns: since,
                                    suspected_cause: "no_tick_data".into(),
                                },
                            ),
                        ),
                    });
            }
            crate::graph::NodeStatus::Down { since }
                if now - since < 200_000_000 =>
            {
                signals.push(proto::TopologySignal {
                        r#type: proto::SignalType::NodeDown as i32,
                        severity: proto::Severity::Critical as i32,
                        context: format!(
                            "{}:{} venue appears DOWN. No ticks for {}s.",
                            id.venue, id.symbol, (now - since) / 1_000_000_000
                        ),
                        first_seen_ns: since,
                        duration_windows: 1,
                        signal_data: Some(
                            proto::topology_signal::SignalData::NodeHealth(
                                proto::NodeHealthSignal {
                                    venue: id.venue.clone(),
                                    symbol: id.symbol.clone(),
                                    event: "down".into(),
                                    since_ns: since,
                                    suspected_cause: "venue_maintenance".into(),
                                },
                            ),
                        ),
                    });
            }
            _ => {}
        }
    }
}

pub(crate) use crate::graph::now_ns;

#[cfg(test)]
mod tests {
    use super::*;
    use crate::graph::{Edge, EdgeId, EdgeOrigin, EdgeType, GraphConfig,
        NodeId, NodeStatus, SheafGraph, Timeframe};
    use crate::laplacian::LaplacianResult;

    /// When `arbitrage_signal_threshold_bps` is raised to 10.0, a 7 bps spread
    /// should NOT emit a signal. Proves the config threshold is wired.
    #[test]
    fn test_arbitrage_signal_respects_config_threshold() {
        let now = crate::graph::now_ns();

        // Custom config: threshold at 10 bps instead of default 5.
        let config = GraphConfig {
            arbitrage_signal_threshold_bps: 10.0,
            ..Default::default()
        };

        let mut graph = SheafGraph::new(
            vec![("A".into(), "ETH".into()), ("B".into(), "ETH".into())],
            vec![Timeframe::T1m],
            config,
        );

        // Set node A price to 100.0, node B to 99.93 — spread = 7 bps.
        let id_a = NodeId { venue: "A".into(), symbol: "ETH".into(), timeframe: Timeframe::T1m };
        let id_b = NodeId { venue: "B".into(), symbol: "ETH".into(), timeframe: Timeframe::T1m };

        if let Some(n) = graph.nodes.get_mut(&id_a) {
            n.last_price = Some(100.0);
            n.last_tick_ns = Some(now);
            n.status = NodeStatus::Active;
        }
        if let Some(n) = graph.nodes.get_mut(&id_b) {
            n.last_price = Some(99.93);
            n.last_tick_ns = Some(now);
            n.status = NodeStatus::Active;
        }

        // Add an arbitrage edge between A and B.
        let edge_id = EdgeId {
            a: id_a.clone(),
            b: id_b.clone(),
            edge_type: EdgeType::Arbitrage,
        };
        graph.edges.insert(
            edge_id.clone(),
            Edge {
                id: edge_id,
                status: crate::graph::EdgeStatus::Active,
                weight: 1.0,
                discovered_at: now,
                origin: EdgeOrigin::Discovered,
            },
        );

        // Extract signals: spread is 7 bps, which is below 10 bps threshold.
        // Should produce NO arbitrage signal.
        let dummy_laplacian = LaplacianResult {
            node_count: 2,
            eigenvalues: vec![0.0, 1.0],
            eigen_gap: 1.0,
            algebraic_connectivity: 1.0,
            spectral_radius: 1.0,
            compute_ns: 0,
        };
        let signals = extract_signals(&graph, &dummy_laplacian, 0);

        let arb_signals: Vec<_> = signals
            .iter()
            .filter(|s| s.r#type == crate::proto::SignalType::ArbitrageEdge as i32)
            .collect();

        assert!(
            arb_signals.is_empty(),
            "Expected 0 arbitrage signals at 7 bps with threshold 10 bps, got {}",
            arb_signals.len()
        );
    }
}

//! Tick data types — Arrow-native columnar format.

// @anchor infra:sheaf:tick
// @tags infra

use arrow::array::{Float64Array, StringArray, TimestampNanosecondArray};
use arrow::datatypes::{DataType, Field, Schema, TimeUnit};
use arrow::record_batch::RecordBatch as ArrowRecordBatch;
use std::sync::Arc;

#[derive(Debug, Clone)]
pub struct Tick {
    pub venue: String,
    pub symbol: String,
    pub price: f64,
    pub size: f64,
    pub event_ts: i64,
    pub ts: i64,
}

#[derive(Debug, Clone)]
pub struct TickBatch {
    pub batch: ArrowRecordBatch,
    pub window_close_ts: i64,
    pub raw_count: usize,
}

impl TickBatch {
    pub fn schema() -> Schema {
        Schema::new(vec![
            Field::new("venue", DataType::Utf8, false),
            Field::new("symbol", DataType::Utf8, false),
            Field::new("price", DataType::Float64, false),
            Field::new("size", DataType::Float64, false),
            Field::new(
                "event_ts",
                DataType::Timestamp(TimeUnit::Nanosecond, None),
                false,
            ),
            Field::new(
                "ts",
                DataType::Timestamp(TimeUnit::Nanosecond, None),
                false,
            ),
        ])
    }

    pub fn from_ticks(ticks: &[Tick], window_close_ts: i64) -> Self {
        let raw_count = ticks.len();

        let venues: Vec<&str> = ticks.iter().map(|t| t.venue.as_str()).collect();
        let symbols: Vec<&str> = ticks.iter().map(|t| t.symbol.as_str()).collect();
        let prices: Vec<f64> = ticks.iter().map(|t| t.price).collect();
        let sizes: Vec<f64> = ticks.iter().map(|t| t.size).collect();
        let event_tss: Vec<i64> = ticks.iter().map(|t| t.event_ts).collect();
        let tss: Vec<i64> = ticks.iter().map(|t| t.ts).collect();

        let batch = ArrowRecordBatch::try_new(
            Arc::new(Self::schema()),
            vec![
                Arc::new(StringArray::from(venues)),
                Arc::new(StringArray::from(symbols)),
                Arc::new(Float64Array::from(prices)),
                Arc::new(Float64Array::from(sizes)),
                Arc::new(TimestampNanosecondArray::from(event_tss)),
                Arc::new(TimestampNanosecondArray::from(tss)),
            ],
        )
        .expect("TickBatch schema mismatch");

        Self {
            batch,
            window_close_ts,
            raw_count,
        }
    }

    pub fn into_polars(self) -> polars::prelude::DataFrame {
        // TODO: proper Arrow→Polars conversion.
        // For scaffold, return empty DataFrame — conversion requires
        // Box<dyn Array> which needs ArrayRef → owned conversion.
        let _ = self;
        polars::prelude::DataFrame::empty()
    }

    pub fn len(&self) -> usize {
        self.batch.num_rows()
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }
}

//! Tick source abstraction.
//!
//! Two implementations:
//! - `ExchangeSource` — direct exchange WebSocket connection
//! - `TestudoSource` — wraps Testudo's existing gRPC/WS pipe
//!
//! Sources are orchestrated by `SourceOrchestrator`.

// @anchor infra:sheaf:source
// @tags infra

use crate::tick::TickBatch;
use futures::stream::Stream;
use std::pin::Pin;

// ── Venue identifier ──

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct VenueId(pub String);

// ── Health ──

#[derive(Debug, Clone)]
pub struct SourceHealth {
    pub venue: VenueId,
    pub state: SourceState,
    pub ticks_per_min: f64,
    pub last_tick_age_ms: Option<u64>,
    pub reconnect_attempt: u32,
    pub reconnect_exhausted: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub enum SourceState {
    Healthy,
    Stale { stale_since: i64 },
    Reconnecting { since: i64, attempt: u32 },
    Dead { since: i64 },
}

// ── Reconnect policy ──

#[derive(Debug, Clone)]
pub struct ReconnectPolicy {
    pub max_attempts: u32,
    pub initial_backoff_ms: u64,
    pub max_backoff_ms: u64,
    pub multiplier: f64,
}

impl Default for ReconnectPolicy {
    fn default() -> Self {
        Self {
            max_attempts: 10,
            initial_backoff_ms: 500,
            max_backoff_ms: 30_000,
            multiplier: 2.0,
        }
    }
}

// ── Subscription ──

#[derive(Debug, Clone)]
pub struct Subscription {
    pub symbol: String,
    pub data_type: TickDataType,
}

#[derive(Debug, Clone)]
pub enum TickDataType {
    Trades,
}

// ── Source priority ──

#[derive(Debug, Clone)]
pub enum TickSourcePriority {
    Direct,
    Merge,
    PreferTestudo,
}

// ── TickSource trait ──

/// The unified tick source interface.
/// Returns a boxed stream of TickBatch.
#[async_trait::async_trait]
pub trait TickSource: Send + Sync {
    fn venue_id(&self) -> &VenueId;

    async fn stream(
        &mut self,
        subscriptions: Vec<Subscription>,
    ) -> Result<
        Pin<Box<dyn Stream<Item = Result<TickBatch, TickSourceError>> + Send + 'static>>,
        TickSourceError,
    >;

    fn health(&self) -> SourceHealth;

    async fn shutdown(&mut self) -> Result<(), TickSourceError>;
}

// ── TickSource error ──

#[derive(Debug, thiserror::Error)]
pub enum TickSourceError {
    #[error("connection failed: {0}")]
    ConnectionFailed(String),
    #[error("disconnected unexpectedly")]
    Disconnected,
    #[error("reconnect exhausted after {attempts} attempts")]
    ReconnectExhausted { attempts: u32 },
    #[error("parse error: {0}")]
    ParseError(String),
    #[error("invalid tick: {0}")]
    InvalidTick(String),
    #[error("stale feed: no ticks for {staleness_ms}ms")]
    StaleFeed { staleness_ms: u64 },
    #[error("backpressure: downstream consumer too slow")]
    Backpressure,
    #[error("unknown venue: {0}")]
    UnknownVenue(String),
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),
}

