    FOR EACH ROW EXECUTE FUNCTION notify_queue_database();

-- Cache Table (UNLOGGED for performance, per-query TTL check)
CREATE UNLOGGED TABLE IF NOT EXISTS cache_entries (
    key TEXT PRIMARY KEY,
    value JSONB NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL
);

-- Request-Response Table for RPC-style operations
CREATE TABLE IF NOT EXISTS request_responses (
    request_id UUID PRIMARY KEY,
    response JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE OR REPLACE FUNCTION notify_response() RETURNS TRIGGER AS $$
BEGIN
    PERFORM pg_notify('response_' || NEW.request_id::text, '');
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER response_notify
    AFTER INSERT ON request_responses
    FOR EACH ROW EXECUTE FUNCTION notify_response();

-- Server-side session tracking for token rotation and revocation

CREATE TABLE user_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    refresh_token_hash VARCHAR(255) NOT NULL,
    ip_address VARCHAR(45),
    user_agent TEXT,
    is_revoked BOOLEAN DEFAULT FALSE,
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    last_used_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_user_sessions_user_id ON user_sessions(user_id);
CREATE INDEX idx_user_sessions_token_hash ON user_sessions(refresh_token_hash);
CREATE INDEX idx_user_sessions_active ON user_sessions(expires_at)
    WHERE is_revoked = FALSE;

-- Wallet-primary users table migration
-- Replaces email/password auth with wallet_address as sole identity

-- Add wallet_address as new identity column
ALTER TABLE users ADD COLUMN wallet_address VARCHAR(42);
CREATE UNIQUE INDEX idx_users_wallet_address ON users(wallet_address);

-- Drop email-based auth columns and infrastructure
DROP TRIGGER IF EXISTS update_users_updated_at ON users;
DROP INDEX IF EXISTS idx_users_email;
ALTER TABLE users DROP CONSTRAINT IF EXISTS check_email_not_empty;
ALTER TABLE users DROP CONSTRAINT IF EXISTS check_email_format;
ALTER TABLE users DROP CONSTRAINT IF EXISTS check_password_hash_not_empty;
ALTER TABLE users DROP COLUMN IF EXISTS email;
ALTER TABLE users DROP COLUMN IF EXISTS password_hash;
ALTER TABLE users DROP COLUMN IF EXISTS email_verified;

-- Make wallet_address NOT NULL after column exists
-- (existing rows must be backfilled or truncated before applying this)
ALTER TABLE users ALTER COLUMN wallet_address SET NOT NULL;

-- Wallet address format constraint (0x + 40 hex chars)
-- Lowercase-only constraint — addresses are normalized to lowercase on insert
ALTER TABLE users ADD CONSTRAINT check_wallet_address_format
    CHECK (wallet_address ~ '^0x[0-9a-f]{40}$');

-- Re-create updated_at trigger (was dropped with email infrastructure)
CREATE TRIGGER update_users_updated_at
    BEFORE UPDATE ON users
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

//! Onboarding status types for GET /api/v1/onboarding/status.
//!
//! Provides a single-call readiness endpoint for AI agents (Hermes, pi, OpenClaw)
//! to discover what the user needs before trading can begin.

// @anchor exchange:router:onboarding-types
// @tags api

use serde::Serialize;
use uuid::Uuid;

use common_utils::risk::RiskConfig;

/// Response from GET /api/v1/onboarding/status.
#[derive(Debug, Serialize)]
pub struct OnboardingStatus {
    /// True when the user has everything needed to start trading.
    pub is_ready: bool,

    /// Prescriptive next action for the agent to guide the user through.
    pub next_step: OnboardingStep,

    /// Human-readable descriptions of what's missing.
    /// Empty when is_ready is true.
    pub missing: Vec<String>,

    /// Available exchanges with credential requirements.
    /// Present when next_step is "connect_exchange".
    #[serde(skip_serializing_if = "Option::is_none")]
    pub available_exchanges: Option<Vec<ExchangeOption>>,

    /// Pending agent wallet that needs EIP-712 approval.
    /// Present when next_step is "approve_agent_wallet".
    #[serde(skip_serializing_if = "Option::is_none")]
    pub pending_agent_wallet: Option<PendingAgentWallet>,

    /// Whether the user has any trade history at all.
    pub has_trades: bool,

    /// Current risk configuration (so agent can surface settings).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub risk_config: Option<RiskConfigSummary>,
}

#[derive(Debug, Serialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum OnboardingStep {
    /// Agent should guide user through SIWE/SIWS authentication.
    Authenticate,

    /// No exchange account connected. Agent should present exchange options.
    ConnectExchange,

    /// Agent wallet initialized but not approved. Agent should guide through EIP-712 signing.
    ApproveAgentWallet,

    /// Risk config is at defaults. Agent should offer to customize.
    ConfigureRisk,

    /// Everything is ready. Agent can start trading.
    ReadyToTrade,
}

#[derive(Debug, Serialize)]
pub struct ExchangeOption {
    pub id: String,
    pub name: String,
    #[serde(rename = "type")]
    pub exchange_type: String,
    pub required_credentials: Vec<String>,
}

#[derive(Debug, Serialize)]
pub struct PendingAgentWallet {
    pub account_id: Uuid,
    pub agent_address: String,
    pub wallet_address: String,
    /// True if an existing agent wallet needs re-authorization.
    pub requires_reauthorization: bool,
}

#[derive(Debug, Serialize)]
pub struct RiskConfigSummary {
    pub account_risk_percent: String,
    pub max_leverage: i32,
    pub daily_drawdown_limit: Option<String>,
    pub stop_loss_required: bool,
}

impl From<RiskConfig> for RiskConfigSummary {
    fn from(config: RiskConfig) -> Self {
        Self {
            account_risk_percent: config.account_risk_percent.to_string(),
            max_leverage: config.max_leverage as i32,
            daily_drawdown_limit: config
                .daily_max_drawdown_percent
                .map(|d| d.to_string()),
            stop_loss_required: config.require_stop_loss,
        }
    }
}

